const signs: [string, string, string][] = [
  ["Small changes require disproportionate effort", "A single field or rule change crosses modules, reports and integrations. The business postpones useful improvements because nobody can forecast the consequences.", "Trace one recent change: how much work was implementation, testing, approval and recovery? Identify the coupling before estimating a rewrite."],
  ["Releases are increasingly difficult", "Deployments require a specialist, a long manual checklist or a period when users must avoid the system. This narrows the organization's ability to respond.", "Review release frequency, failure modes, rollback steps and test coverage. A better delivery path may be the first modernization step."],
  ["Critical frameworks or dependencies are difficult to support", "The team cannot obtain updates or run essential tooling on a supported environment. This is a supportability issue even if day-to-day features still work.", "Inventory versions, vendors and dependency paths. Evaluate supported upgrade options before assuming all business behavior must be rebuilt."],
  ["Integration requires repeated workarounds", "New systems consume exports, query production tables directly or rely on manual re-entry because contracts between systems are unclear.", "Map record ownership and test one supported API or event seam. Define validation, retries and failure reconciliation."],
  ["Teams rely on spreadsheets around the application", "Work continues outside the system because a workflow no longer fits, a report cannot be trusted or approvals have no clear home.", "Follow one spreadsheet from input to decision. Determine whether the fix is configuration, integration, user experience or process ownership."],
  ["One or two people hold most system knowledge", "A release, incident or rule change waits for the person who knows an undocumented exception. This is a continuity risk, not a criticism of that person.", "Document critical rules and recovery steps; pair on a bounded change and test whether another engineer can reproduce the outcome."],
  ["Troubleshooting takes longer than it should", "Teams know something failed but cannot connect the user action to an application request, integration message or data change.", "Add traceable IDs, useful logs and health signals around one incident-prone workflow before a broad observability programme."],
  ["New business requirements do not fit cleanly", "Every new product, channel or region creates special-case code, parallel tools or process exceptions. The application model may no longer reflect the business model.", "Compare a representative new requirement with existing domain boundaries. Decide whether to extend, isolate a capability or evaluate replacement."],
  ["Data is difficult to extract or trust", "Reporting depends on unexplained exports, inconsistent identifiers or undocumented transformations. Even a new front end cannot fix an ambiguous source of truth.", "Name authoritative records, retention and reconciliation rules. Treat data work as its own modernization track."],
  ["Infrastructure changes are harder than application changes", "Hosting and runtime assumptions are embedded throughout the software. A routine platform update becomes a high-risk application event.", "Inventory file, network, scheduler, runtime and configuration dependencies. Test whether a supported runtime upgrade or replatform is feasible."],
  ["Security or compliance requirements are harder to satisfy", "Required identity, access, audit, patching or retention controls cannot be implemented reliably in the current environment.", "Define the actual obligation with accountable security and legal owners. Review specific controls and remediation paths; do not infer compliance from a cloud move."],
  ["The application limits business decisions", "A viable service, product or operational change is repeatedly rejected because the system cannot support it within a responsible timeframe.", "Document the foregone option and the technical constraint. This connects modernization priority to business consequence without inventing ROI."],
];
const riskSections: ArticleSection[] = [
  { id: "age", title: "Age is not the issue. Constraint is.", answer: "A legacy application becomes a business risk when its limitations materially affect delivery, operations, continuity or decisions—not when it reaches an arbitrary age.", paragraphs: ["An older application can be stable, well understood and appropriate for its purpose. A recently built application can already be hard to release or integrate. The label 'legacy' often says more about its position in the organization than its condition. Ask what necessary work is becoming harder, what consequence follows and whether a targeted change can remove that constraint.", "Some signs in this guide are technical: unsupported dependencies or weak observability. Others are operational: knowledge concentrated in one person or people rebuilding the process in spreadsheets. The business consequence decides priority. A slow report and an inability to meet a binding security obligation should not be placed in the same queue merely because both involve old software."] },
  { id: "radar", title: "The Xyncwave Legacy Application Risk Radar", variant: "framework", answer: "Examine business fit, changeability, supportability, integration, operations and knowledge together. A single weak dimension can matter, but patterns across dimensions usually reveal the next responsible investigation.", table: { headers: ["Dimension", "Diagnostic question", "Useful evidence"], rows: [["Business fit", "Does the system still support necessary work?", "Workarounds and deferred decisions"], ["Changeability", "Can a bounded change be released safely?", "Lead time and release history"], ["Supportability", "Can dependencies and runtime be maintained?", "Version and vendor inventory"], ["Integration", "Can dependable contracts connect systems?", "Data ownership and interface failures"], ["Operations", "Can teams observe and recover failures?", "Incident and recovery records"], ["Knowledge", "Can more than one person operate it?", "Documentation and handover exercise"]] }, paragraphs: ["This is a directional framework, not a formal risk rating. It helps decide where to gather evidence. An unknown dimension deserves discovery rather than an optimistic zero or an automatic worst-case assumption."] },
  ...signs.map(([title, symptom, action], index): ArticleSection => ({ id: `sign-${index + 1}`, title: `${index + 1}. ${title}`, answer: symptom, paragraphs: [action, index % 2 === 0 ? "Ask the process owner what necessary action is delayed and what the current workaround depends on. Then ask engineering whether a focused intervention can change that condition without disturbing useful behavior. The answer may be documentation, integration or platform support rather than replacement." : "Separate the observable symptom from its cause. A recurring incident may come from a dependency, an unclear process or a missing operational control. Record a real example and agree what evidence would show the constraint has eased before choosing an implementation path."], ...(index === 3 ? { links: [{ label: "System integration strategy", to: "/insights/system-integration-strategy" }, { label: "API & System Integration", to: "/solutions/integration" }] } : index === 8 ? { links: [{ label: "Data engineering for growing businesses", to: "/insights/data-engineering-growing-businesses" }] } : {}) })),
  { id: "priority", title: "Modernize Now / Plan / Monitor Matrix", variant: "framework", answer: "Compare business impact with the strength of the technical constraint. The combination determines urgency—not age alone.", table: { headers: ["Business impact", "Technical constraint", "Directional action"], rows: [["Low", "Low", "Monitor and maintain"], ["Low", "High", "Targeted improvement for supportability"], ["High", "Low", "Review process or product fit"], ["High", "High", "Prioritize modernization discovery"]] }, paragraphs: ["'Modernize now' does not mean 'rewrite now.' It means assign an owner, examine evidence and act on the most consequential limitation. A system with critical security or continuity exposure may need immediate containment even while the longer-term path remains undecided."] },
  { id: "not-every", title: "Not every legacy application needs modernization", answer: "Maintain the application when it still fits its purpose, support and recovery are acceptable, integrations are dependable and change demand is modest.", paragraphs: ["The goal is not a uniform technology estate. An older billing or operational tool may be understood and stable. Replacing it can introduce user disruption and migration risk without creating new value. Monitor vendor support, backup restoration, ownership and the cost of safe change; intervene when evidence warrants it.", "Conversely, do not use stability as an excuse to defer a critical unsupported dependency or a concentrated knowledge risk indefinitely. A deliberate maintenance decision should include an owner, a review trigger and a practical recovery path."] },
  { id: "technical-debt", title: "Technical debt becomes business risk through a consequence", answer: "Think of risk as technical condition × business consequence. A difficult module matters more when it blocks a critical product decision or makes a necessary control impossible.", paragraphs: ["Technical debt describes compromises in code, architecture, testing or operations that make future work harder. Some debt is manageable and can be serviced during ordinary delivery. It becomes a business priority when the inability to change, restore, integrate or support the system has a meaningful operational or strategic consequence.", "Avoid false precision: without an observed baseline, a percentage risk score says little. Collect concrete examples instead: a release delayed, an exception routed to a spreadsheet, an integration patched manually or an incident that could not be diagnosed promptly."] },
  { id: "evidence", title: "Collect evidence before assigning urgency", answer: "A useful application review links an observed symptom to a consequence, a plausible cause and the next question that would resolve uncertainty.", paragraphs: ["Choose a representative business process and follow it through the application. Record what the user wanted to do, where the system slowed or diverted the work, who intervened and how completion was verified. Compare a normal transaction with an exception. The exception often reveals the rules that a proposed replacement must still support.", "Bring release logs, dependency versions, incident records, interface contracts, spreadsheets and a sample of support requests. These artifacts can distinguish a software design limitation from a policy, training or data-ownership problem. For example, delayed reporting might be caused by manual source reconciliation, not a slow database. A redesign aimed only at query performance would miss the constraint.", "Make uncertainty visible. Mark dependencies as known and tested, known but untested, or unknown. Ask who could approve a change and who would restore service if it failed. This gives both business and engineering leaders a common view of what is established and what still needs investigation."], bullets: ["Symptom: what happened, to whom and how often?", "Consequence: which decision, control or service was affected?", "Cause hypothesis: what application, data or operating condition might explain it?", "Evidence gap: what test or interview would distinguish the alternatives?", "Owner: who can accept the risk or authorize the next step?"] },
  { id: "responses", title: "Five responsible responses to a legacy constraint", answer: "Maintain, contain, improve, modernize or replace are all valid responses when matched to the evidence and business consequence.", subsections: [
    { title: "Maintain and monitor", paragraphs: ["If business fit remains strong and support and recovery are adequate, assign ownership and a review trigger. Avoid change for its own sake, but keep inventory and restore testing current."] },
    { title: "Contain an immediate exposure", paragraphs: ["When an actual support or control gap requires attention, a temporary boundary, access restriction or isolated environment may buy time for a deliberate path. A containment measure is not a substitute for a permanent remediation plan."] },
    { title: "Target one bottleneck", paragraphs: ["A brittle deployment can be stabilized with tests and release practice. A recurring handoff can gain a supported interface. A knowledge gap can be addressed with documentation and pairing. Judge the effect of the bounded change before widening scope."] },
    { title: "Modernize selectively", paragraphs: ["Refactor code, upgrade the framework or replatform when the current system still serves useful business work. Protect existing rules, data and downstream consumers while changing what needs to change."] },
    { title: "Evaluate replacement", paragraphs: ["Where the process no longer fits, compare a package and a custom implementation against real exception paths, data movement and user adoption. The choice is a business-system decision, not a judgment on the age of the current code."] },
  ] },
  { id: "business-conversation", title: "How to bring the risk into a business conversation", answer: "Replace vague warnings about 'legacy technology' with a specific statement of work affected, consequence observed and next test proposed.", paragraphs: ["Instead of saying 'the monolith is risky,' say 'a change to the order rule affects three untested interfaces, so the next release cannot be estimated responsibly until we map those contracts.' Instead of 'we need to move everything to cloud,' say 'the runtime loses support, and a supported upgrade may be possible if the two external dependencies pass compatibility tests.' Each formulation gives a decision-maker a choice and names the evidence needed.", "Avoid turning qualitative findings into invented financial loss. If a manual workaround consumes material effort, sample actual transactions and handling time with operations. If a feature has been deferred, identify the decision owner and the business opportunity affected. If recovery is uncertain, rehearse a restore and document the result. A grounded business case can then be built from verified local information rather than an industry-wide percentage that does not describe this application.", "Prioritize across an application portfolio by business criticality, strength of the constraint, dependency exposure, ability to contain it and readiness for a bounded next step. A severe issue in a low-use system may call for retirement; a moderate constraint in a vital system may deserve careful staged investment."] },
  { id: "next", title: "What happens after the risk is identified?", answer: "Translate the highest-impact constraint into a bounded modernization decision: maintain, improve, refactor, replatform, selectively rebuild or replace.", paragraphs: ["Start with a business owner and a technical owner. Map the affected workflow, application dependency, data responsibility and support obligation. Capture how the constraint shows up today and define an acceptable future condition. Use the modernization decision matrix to compare interventions before funding a programme.", "Sequence the work around continuity: characterize existing behavior, test a representative change, plan coexistence and data reconciliation, then broaden only if the first step proves its value. If the main obstacle is the hosting environment, the cloud migration guide helps separate location from design."], links: [{ label: "Application Modernization: refactor vs replatform vs rebuild vs replace", to: "/insights/application-modernization-refactor-replatform-rebuild-replace" }, { label: "Cloud migration vs cloud modernization", to: "/insights/cloud-migration-vs-cloud-modernization" }, { label: "Application Modernization solution", to: "/solutions/application-modernization" }] },
  { id: "practice", title: "A practical modernization example with clear evidence boundaries", variant: "proof", paragraphs: ["The published cloud-native .NET application modernization case describes work across framework upgrades, APIs, data access, messaging, cloud-hosted workloads and controlled deployments. Its architecture diagram is a representative pattern, not proof that every illustrated service ran together in one production environment.", "It shows the kinds of engineering constraints a team can address while preserving delivery. It does not document a percentage improvement, commercial return, exact project duration or universal path for older applications. A Java, Python or PHP system would require its own dependency and business-fit assessment."], links: [{ label: "See the Application Modernization case study", to: "/case-studies/cloud-native-dotnet-modernization" }, { label: "Software Engineering", to: "/solutions/software-engineering" }] },
  { id: "related", title: "Continue the decision", paragraphs: ["If the radar indicates a meaningful constraint, choose the intervention deliberately. If a platform move is proposed, ask whether the application or only its operating environment needs to change."], links: [{ label: "Application modernization decision matrix", to: "/insights/application-modernization-refactor-replatform-rebuild-replace" }, { label: "Cloud migration vs cloud modernization", to: "/insights/cloud-migration-vs-cloud-modernization" }, { label: "Cloud & Platform Engineering", to: "/solutions/cloud-platform-engineering" }] },
];
